function documentTypeOptions(selected){return [['COMMERCIAL_INVOICE','Commercial Invoice'],['PACKING_LIST','Packing List'],['BILL_OF_LADING','Bill of Lading'],['AIR_WAYBILL','Air Waybill'],['ROAD_CONSIGNMENT_NOTE','CMR / Road Consignment Note'],['CERTIFICATE_OF_ORIGIN','Certificate of Origin'],['INSURANCE_CERTIFICATE','Insurance Certificate'],['INSPECTION_CERTIFICATE','Inspection Certificate'],['BILL_OF_EXCHANGE','Bill of Exchange / Draft'],['BENEFICIARY_CERTIFICATE',"Beneficiary's Certificate"],['QUALITY_CERTIFICATE','Quality / Analysis Certificate'],['COURIER_RECEIPT','Courier Receipt'],['ANNEX','Annex / Anlage'],['OTHER','Other']].map(([value,label])=>`<option value="${value}"${value===selected?' selected':''}>${label}</option>`).join('')}
function openDocumentEdit(button){let dialog=$('#documentEditDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='documentEditDialog';dialog.innerHTML='<form id="documentEditForm"><div class="dialoghead"><div><h2>Dokumentdaten bearbeiten</h2><p id="documentEditName"></p></div><button type="button" class="ghost document-edit-close">×</button></div><input type="hidden" name="id"><div class="form-grid"><label class="wide">Dokumenttyp<select name="type" required></select></label><label>Dokumentdatum<input name="documentDate" type="date"></label><label>Betrag<input name="amount" type="number" min="0" step="0.01"></label><label>Währung<input name="currency" maxlength="3" placeholder="EUR"></label></div><div id="documentEditError" class="error"></div><div class="actions"><button type="button" class="secondary document-edit-close">Abbrechen</button><button type="submit">Änderungen speichern</button></div></form>';document.body.append(dialog);dialog.querySelectorAll('.document-edit-close').forEach(x=>x.onclick=()=>dialog.close());$('#documentEditForm').onsubmit=saveDocumentEdit}const form=$('#documentEditForm');form.elements.id.value=button.dataset.documentEdit;form.elements.type.innerHTML=documentTypeOptions(button.dataset.documentType);form.elements.documentDate.value=button.dataset.documentDate;form.elements.amount.value=button.dataset.documentAmount;form.elements.currency.value=button.dataset.documentCurrency;$('#documentEditName').textContent=button.dataset.documentName;$('#documentEditError').textContent='';dialog.showModal()}
async function saveDocumentEdit(event){event.preventDefault();const form=event.target,payload=Object.fromEntries(new FormData(form).entries()),id=payload.id;delete payload.id;payload.documentDate=payload.documentDate||null;payload.amount=payload.amount===''?null:Number(payload.amount);payload.currency=payload.currency||null;try{await json(`/api/lcs/${activeLc.id}/documents/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#documentEditDialog').close();await show(activeLc.id)}catch(e){$('#documentEditError').textContent='Speichern fehlgeschlagen: '+e.message}}
function extractionLabel(status){return ({GENERATED:'Im LC-Manager erstellt',EXTRACTED:'Text automatisch ausgelesen',OCR_EXTRACTED:'Scan per OCR ausgelesen',NO_TEXT:'Auch per OCR kein Text erkannt',OCR_UNAVAILABLE:'OCR ist derzeit nicht verfügbar',UNSUPPORTED:'Format nicht auslesbar',FAILED:'Auslesen oder OCR fehlgeschlagen',NOT_PROCESSED:'Noch nicht verarbeitet'})[status]||status||'Nicht verarbeitet'}
function renderReview(review,documents=[]){if(!review)return '<div class="empty compact">Prüfung konnte nicht geladen werden.</div>';return reviewGate(review)+`<div class="review-summary"><span class="summary discrepancy">${review.discrepancies} Abweichungen</span><span class="summary warning">${review.warnings} offene Hinweise</span><span class="summary passed">${review.passed} erfüllt</span></div><p class="finding-keyboard-help">${findingShortcutHelp()}</p><div class="review-filter-bar"><label>Befunde anzeigen<select data-review-filter><option value="all">Alle Befunde</option><option value="open">Offene Hinweise / Abweichungen</option><option value="decided">Manuell entschieden</option><option value="discrepancy">Aktuelle Abweichungen</option></select></label><label>Suche<input type="search" data-review-search placeholder="Dokument, Prüfregel oder Text …"></label><small data-review-count aria-live="polite">Alle ${review.results.length} Befunde</small></div><div class="check-list">${review.results.map(r=>`<div class="check ${r.severity.toLowerCase()}" tabindex="0" aria-label="Prüfbefund: ${esc(r.message)}" data-finding-severity="${r.severity}" data-finding-decided="${Boolean(r.reviewDecision)}"><span>${r.severity==='OK'?'✓':r.severity==='WARNING'?'!':'×'}</span><div><b>${label(r.severity)} · ${esc(r.message)}</b>${renderFindingEvidence(r,documents)}${r.reviewDecision?`<small class="check-source"><strong>Manuell geprüft</strong>${r.reviewDecision==='ACCEPTED'?'Als erfüllt bestätigt':'Abweichung bestätigt'} · ${esc(r.reviewedBy)} · ${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(r.reviewedAt))}${r.reviewComment?' · '+esc(r.reviewComment):''}</small>`:''}${currentUser?.role!=='VIEWER'&&(r.severity!=='OK'||r.reviewDecision)?`<div class="review-actions"><button type="button" class="secondary" data-check-decision="ACCEPTED" data-check-code="${esc(r.code)}" data-check-document="${esc(r.documentName||'')}">${r.reviewDecision?'Entscheidung ändern: erfüllt':'Als erfüllt bestätigen'}</button><button type="button" class="danger" data-check-decision="CONFIRMED_DISCREPANCY" data-check-code="${esc(r.code)}" data-check-document="${esc(r.documentName||'')}">${r.reviewDecision?'Entscheidung ändern: Abweichung':'Abweichung bestätigen'}</button></div>`:''}</div></div>`).join('')}</div><p class="hidden" data-review-empty>Keine Befunde für diese Filterauswahl. Die Gesamtbewertung bleibt unverändert.</p>`}

function matchesFindingFilter(severity,decided,text,filter,query){
    const status=filter==='open'?severity!=='OK'&&!decided:filter==='decided'?decided:filter==='discrepancy'?severity==='DISCREPANCY':true;
    return status&&text.toLocaleLowerCase('de').includes(query.trim().toLocaleLowerCase('de'));
}
function applyFindingFilters(event){
    if(!event.target.matches('[data-review-filter],[data-review-search]'))return;
    const toolbar=event.target.closest('.review-filter-bar'),list=toolbar.nextElementSibling;
    const filter=toolbar.querySelector('[data-review-filter]').value,query=toolbar.querySelector('[data-review-search]').value;
    let visible=0;
    const rows=list.querySelectorAll('[data-finding-severity]');
    rows.forEach(row=>{
        const matches=matchesFindingFilter(row.dataset.findingSeverity,row.dataset.findingDecided==='true',row.textContent,filter,query);
        row.classList.toggle('hidden',!matches);if(matches)visible++;
    });
    toolbar.querySelector('[data-review-count]').textContent=visible+' von '+rows.length+' Befunden · Gesamtbewertung unverändert';
    list.nextElementSibling?.classList.toggle('hidden',visible!==0);
}
document.addEventListener('input',applyFindingFilters);
document.addEventListener('change',applyFindingFilters);

function findingShortcut(event){
    if(event.repeat||event.isComposing||event.ctrlKey||event.metaKey||event.altKey||event.shiftKey)return null;
    const settings=findingShortcutSettings();
    if(!settings.enabled)return null;
    return Object.keys(settings.keys).find(action=>settings.keys[action]===event.key.toLowerCase())||null;
}
const defaultFindingKeys={next:'n',previous:'p',ACCEPTED:'a',CONFIRMED_DISCREPANCY:'d'};
function validFindingKeys(keys){return keys&&Object.keys(defaultFindingKeys).every(action=>typeof keys[action]==='string'&&/^[a-z]$/.test(keys[action]))&&new Set(Object.keys(defaultFindingKeys).map(action=>keys[action])).size===4;}
function findingShortcutStorageKey(){return 'lc-finding-shortcuts:'+String(currentUser?.username||'anonymous');}
function findingShortcutSettings(){
    try{const saved=JSON.parse(localStorage.getItem(findingShortcutStorageKey()));if(saved&&typeof saved.enabled==='boolean'&&validFindingKeys(saved.keys))return saved;}catch(error){}
    return {enabled:true,keys:{...defaultFindingKeys}};
}
function findingShortcutHelp(){
    const settings=findingShortcutSettings(),keys=settings.keys;
return (settings.enabled?`Befund mit Tab fokussieren: ${keys.next.toUpperCase()} = nächster, ${keys.previous.toUpperCase()} = vorheriger, ${keys.ACCEPTED.toUpperCase()} = erfüllt, ${keys.CONFIRMED_DISCREPANCY.toUpperCase()} = Abweichung. Enter = zugeordnetes Original öffnen. Entscheidungen werden erst in der anschließenden Abfrage gespeichert.`:'Tastenkürzel sind abgeschaltet.')+' <button type="button" class="secondary" data-shortcut-settings>Tastenkürzel einstellen</button>';
}
document.addEventListener('click',event=>{
    if(!event.target.closest('[data-shortcut-settings]'))return;
    let dialog=$('#findingShortcutDialog');
    if(!dialog){dialog=document.createElement('dialog');dialog.id='findingShortcutDialog';document.body.append(dialog);}
    const settings=findingShortcutSettings();
    dialog.innerHTML='<form class="training-body"><h2>Tastenkürzel für Befunde</h2><p>Gilt für deinen Benutzer in diesem Browser. Jeweils einen unterschiedlichen Buchstaben A–Z wählen.</p><label><input type="checkbox" name="enabled" '+(settings.enabled?'checked':'')+'> Tastenkürzel aktivieren</label>'+Object.entries({next:'Nächster Befund',previous:'Vorheriger Befund',ACCEPTED:'Als erfüllt bestätigen',CONFIRMED_DISCREPANCY:'Abweichung bestätigen'}).map(([action,label])=>`<label>${label}<input name="${action}" value="${settings.keys[action]}" maxlength="1" pattern="[a-zA-Z]" required></label>`).join('')+'<p class="error" role="alert"></p><div class="actions"><button type="button" data-shortcut-cancel>Abbrechen</button><button type="button" data-shortcut-reset>Standardwerte</button><button type="submit">Speichern</button></div></form>';
    const form=dialog.querySelector('form');
    dialog.querySelector('[data-shortcut-cancel]').onclick=()=>dialog.close();
    dialog.querySelector('[data-shortcut-reset]').onclick=()=>{form.elements.enabled.checked=true;Object.entries(defaultFindingKeys).forEach(([action,key])=>form.elements[action].value=key);};
    form.onsubmit=event=>{
        event.preventDefault();const keys=Object.fromEntries(Object.keys(defaultFindingKeys).map(action=>[action,form.elements[action].value.toLowerCase()]));
        if(!validFindingKeys(keys)){form.querySelector('.error').textContent='Bitte vier unterschiedliche Buchstaben A–Z wählen.';return;}
        try{localStorage.setItem(findingShortcutStorageKey(),JSON.stringify({enabled:form.elements.enabled.checked,keys}));document.querySelectorAll('.finding-keyboard-help').forEach(item=>item.innerHTML=findingShortcutHelp());dialog.close();}
        catch(error){form.querySelector('.error').textContent='Einstellungen konnten in diesem Browser nicht gespeichert werden.';}
    };
    dialog.showModal();
});
document.addEventListener('keydown',event=>{
    const row=event.target;
    if(!row.matches?.('[data-finding-severity]')||row.isContentEditable||!row.getClientRects().length||document.querySelector('dialog[open]'))return;
    if(event.key==='Enter'&&!event.repeat&&!event.isComposing&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.shiftKey&&findingShortcutSettings().enabled){
        const original=row.querySelector('[data-finding-original]');
        if(original){event.preventDefault();original.click();}return;
    }
    const action=findingShortcut(event);if(!action)return;
    const rows=[...row.parentElement.querySelectorAll('[data-finding-severity]')].filter(item=>item.getClientRects().length);
    if(action==='next'||action==='previous'){
        event.preventDefault();
        const index=rows.indexOf(row)+(action==='next'?1:-1);
        const target=rows[Math.max(0,Math.min(rows.length-1,index))];
        target?.focus();target?.scrollIntoView({block:'nearest'});
    }else{
        const button=row.querySelector(`[data-check-decision="${action}"]`);
        if(button&&!button.disabled){event.preventDefault();button.click();}
    }
});

function findingDocumentLink(result,documents){
    if(!result.documentName)return '';
    const matches=documents.filter(document=>document.originalFilename===result.documentName);
    if(matches.length!==1)return '<p>Originaldokument nicht eindeutig zugeordnet. Bitte in der Dokumentenakte auswählen.</p>';
    const document=matches[0];
    if(!/\.(pdf|png|jpe?g)$/i.test(document.originalFilename))return '<p>Original bitte über die Dokumentenakte herunterladen.</p>';
    return `<p><a class="button-link secondary" data-finding-original target="_blank" rel="noopener" href="/api/documents/${encodeURIComponent(document.id)}/preview">Originaldokument öffnen</a> <button type="button" class="secondary" data-document-window="/api/documents/${encodeURIComponent(document.id)}/preview">Separates Fenster</button></p>`;
}
let examinationDocumentWindow=null;
let examinationDocumentLcId=null;
const workspacePresetStorageKey='corporate-lc-manager.workspace-preset';
let examinationWorkspaceWindows=[];
const examinationWorkspaceTabId=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const examinationWorkspacePanel=new URLSearchParams(location.search).get('workspace');
const examinationWorkspaceChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('corporate-lc-manager-examination-v1'):null;
let receivingSynchronizedLcSelection=false;
let synchronizedLcSelectionQueue=Promise.resolve();
examinationWorkspaceChannel?.addEventListener('message',event=>{
    const message=event.data;
    if(message?.type==='WORKSPACE_READY'&&message.source!==examinationWorkspaceTabId){if(activeLc?.id)examinationWorkspaceChannel?.postMessage({type:'LC_SELECTED',lcId:activeLc.id,source:examinationWorkspaceTabId});return;}
    if(message?.type!=='LC_SELECTED'||message.source===examinationWorkspaceTabId||typeof message.lcId!=='string'||activeLc?.id===message.lcId)return;
    synchronizedLcSelectionQueue=synchronizedLcSelectionQueue.then(async()=>{
        if(activeLc?.id===message.lcId)return;
        receivingSynchronizedLcSelection=true;
        try{await show(message.lcId)}finally{receivingSynchronizedLcSelection=false}
    }).catch(()=>{receivingSynchronizedLcSelection=false});
});
