async function loadSwiftFile(inputId,textareaId,nameId,errorId){const input=$(inputId),file=input.files?.[0];if(!file)return;if(file.size>1048576){input.value='';$(nameId).textContent='TXT oder SWIFT, maximal 1 MB';$(errorId).textContent='Die Datei ist größer als 1 MB.';return}try{$(textareaId).value=await file.text();$(nameId).textContent=`${file.name} · ${fileSize(file.size)}`;$(errorId).textContent=''}catch(e){$(errorId).textContent='Die Datei konnte nicht gelesen werden.'}}
function swiftFields(raw){const result=[];const pattern=/^:(\d{2}[A-Z]?):(.*?)(?=^:\d{2}[A-Z]?:|$)/gms;for(const match of String(raw||'').matchAll(pattern))result.push({code:match[1],value:match[2].trim()});return result}
function ensureCorrectionUi(){if($('#correctionBox'))return;const box=document.createElement('section');box.id='correctionBox';box.className='correction-box';box.innerHTML=`<h3>Angaben ergänzen oder verschieben</h3><p>Werte aus einem anderen Standardfeld oder aus der ursprünglichen SWIFT-Nachricht übernehmen.</p><div class="move-grid"><label>Quelle<select id="moveSource"></select></label><label>Ziel<select id="moveTarget"><option value="applicant">Applicant</option><option value="beneficiary">Beneficiary</option><option value="issuingBank">Issuing Bank</option><option value="advisingBank">Advising Bank</option><option value="expiryPlace">Ablaufort</option></select></label><button type="button" id="copyField" class="secondary">Übernehmen</button><button type="button" id="moveField">Verschieben</button></div><small>Übernehmen lässt die Quelle bestehen. Verschieben leert zusätzlich ein Standardfeld. Die Original-SWIFT-Nachricht bleibt unverändert.</small><label class="block-label">Erforderliche Dokumente – eine Angabe pro Zeile<textarea id="requiredDocumentsEdit" class="compact-textarea"></textarea></label><div class="sectionhead compact-head"><div><h3>Weitere Angaben</h3><p>Frei benennbare Informationen ohne passendes Standardfeld.</p></div><button type="button" id="addAdditionalField" class="secondary">+ Angabe</button></div><div id="additionalFieldsEdit" class="additional-fields"></div>`;$('#editForm').insertBefore(box,$('#editError'));$('#addAdditionalField').onclick=()=>addAdditionalRow('','');$('#copyField').onclick=()=>transferField(false);$('#moveField').onclick=()=>transferField(true)}
