let activeDocumentDraftId=null;
function draftStatusLabel(status){return({DRAFT:'Entwurf',REVIEWED:'Geprüft',FINAL:'Final'})[status]||status}
function draftRows(drafts){return drafts.length?drafts.map(draft=>`<div class="draft-document-row"><div><b>${esc(generatedDocumentTypes[draft.documentType]?.title||draft.documentType)} · ${esc(draft.documentNumber)}</b><small>Version ${draft.version+1} · ${esc(draft.updatedBy)} · ${new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(draft.updatedAt))}</small></div><span class="badge draft-status-${draft.status.toLowerCase()}">${draftStatusLabel(draft.status)}</span><div class="draft-document-actions">${draft.status!=='FINAL'&&currentUser.role!=='VIEWER'?`<button type="button" class="secondary" data-draft-edit="${draft.id}">Bearbeiten</button>`:''}${draft.status==='DRAFT'&&currentUser.role!=='VIEWER'?`<button type="button" class="secondary" data-draft-status="REVIEWED" data-draft-id="${draft.id}">Als geprüft markieren</button>`:''}${draft.status==='REVIEWED'&&currentUser.role!=='VIEWER'?`<button type="button" class="secondary" data-draft-status="DRAFT" data-draft-id="${draft.id}">Zur Bearbeitung</button><button type="button" data-draft-status="FINAL" data-draft-id="${draft.id}">Finalisieren</button>`:''}${draft.status==='FINAL'?`<button type="button" class="secondary" data-draft-generate="PDF" data-draft-id="${draft.id}">PDF erzeugen</button><button type="button" class="secondary" data-draft-generate="DOCX" data-draft-id="${draft.id}">Word erzeugen</button>`:''}${draft.status!=='FINAL'&&currentUser.role!=='VIEWER'?`<button type="button" class="ghost danger-text" data-draft-delete="${draft.id}">Löschen</button>`:''}</div></div>`).join(''):'<div class="empty compact">Noch keine Dokumententwürfe vorhanden.</div>'}
