function setupDocumentBatchUpload(){const form=$('#uploadForm'),input=form?.elements.file;if(!form||!input)return;auditLabels.DOCUMENT_BATCH_UPLOADED='Dokumenten-Batch hochgeladen';input.multiple=true;input.closest('label').firstChild.textContent='Dateien oder ZIP-Archive';[...form.querySelectorAll('.form-grid>label')].slice(1).forEach(label=>label.classList.add('hidden'));const preview=document.createElement('div');preview.id='documentBatchPreview';preview.className='document-batch-preview hidden';$('#uploadError').before(preview);const types=[['COMMERCIAL_INVOICE','Handelsrechnung'],['PACKING_LIST','Packliste'],['BILL_OF_LADING','Konnossement'],['AIR_WAYBILL','Luftfrachtbrief'],['ROAD_CONSIGNMENT_NOTE','CMR'],['CERTIFICATE_OF_ORIGIN','Ursprungszeugnis'],['INSURANCE_CERTIFICATE','Versicherungszertifikat'],['INSPECTION_CERTIFICATE','Inspektionszertifikat'],['BILL_OF_EXCHANGE','Wechsel'],['BENEFICIARY_CERTIFICATE','Begünstigtenzertifikat'],['QUALITY_CERTIFICATE','Qualitätszertifikat'],['COURIER_RECEIPT','Kurierbeleg'],['ANNEX','Anlage'],['OTHER','Sonstiges']];const suggest=name=>{name=name.toLowerCase();if(/invoice|rechnung/.test(name))return'COMMERCIAL_INVOICE';if(/packing|packliste/.test(name))return'PACKING_LIST';if(/bill.?of.?lading|(^|[-_ ])bl([-_ .]|$)/.test(name))return'BILL_OF_LADING';if(/airway|air-waybill|awb/.test(name))return'AIR_WAYBILL';if(/cmr/.test(name))return'ROAD_CONSIGNMENT_NOTE';if(/origin|ursprung/.test(name))return'CERTIFICATE_OF_ORIGIN';if(/insurance|versicherung/.test(name))return'INSURANCE_CERTIFICATE';if(/inspection|inspektion/.test(name))return'INSPECTION_CERTIFICATE';if(/draft|bill.?of.?exchange|wechsel/.test(name))return'BILL_OF_EXCHANGE';if(/beneficiary.?certificate/.test(name))return'BENEFICIARY_CERTIFICATE';if(/quality|analysis|analyse/.test(name))return'QUALITY_CERTIFICATE';if(/courier|dhl|fedex/.test(name))return'COURIER_RECEIPT';return'ANNEX'};input.onchange=()=>{const files=[...input.files];preview.classList.toggle('hidden',!files.length);preview.innerHTML=files.length?`<b>${files.length} Quelldatei${files.length===1?'':'en'} vor dem Upload prüfen</b>${files.map((file,index)=>`<div class="document-batch-row"><div><strong>${esc(file.name)}</strong><small>${fileSize(file.size)}${file.name.toLowerCase().endsWith('.zip')?' · Inhalt wird sicher entpackt und automatisch klassifiziert':''}</small></div><select data-batch-type="${index}" ${file.name.toLowerCase().endsWith('.zip')?'disabled':''}>${types.map(([value,label])=>`<option value="${value}" ${value===suggest(file.name)?'selected':''}>${label}</option>`).join('')}</select></div>`).join('')}`:''};form.addEventListener('reset',()=>setTimeout(()=>{preview.classList.add('hidden');preview.innerHTML=''},0));form.onsubmit=async event=>{event.preventDefault();if(!activeLc||!input.files.length)return;$('#uploadError').textContent='';const body=new FormData();[...input.files].forEach((file,index)=>{body.append('file',file);body.append('types',preview.querySelector(`[data-batch-type="${index}"]`)?.value||'ANNEX')});try{const imported=await json(`/api/lcs/${activeLc.id}/documents/batch`,{method:'POST',body});preview.innerHTML=`<div class="success-message"><b>${imported.length} Dokument${imported.length===1?'':'e'} erfolgreich übernommen.</b></div>${imported.map(document=>`<div class="document-batch-result"><span>✓</span><div><b>${esc(document.originalFilename)}</b><small>${esc(document.typeLabel)} · ${esc(document.extractionStatus)}</small></div></div>`).join('')}<div class="actions"><button type="button" id="finishBatchUpload">Zur Dokumentenakte</button></div>`;$('#finishBatchUpload').onclick=async()=>{$('#uploadDialog').close();await show(activeLc.id);activateDossierSection('documents')}}catch(e){$('#uploadError').textContent='Batch-Upload fehlgeschlagen: '+e.message}}}
function ensureRoleUi(){const form=$('#userForm'),select=form.elements.role;select.name='roleId';const button=document.createElement('button');button.type='button';button.id='manageRoles';button.className='secondary';button.textContent='Rollen verwalten';$('#newUser').before(button);const dialog=document.createElement('dialog');dialog.id='rolesDialog';dialog.className='wide-dialog';dialog.innerHTML='<div class="dialoghead"><div><h2>Rollen & Rechte</h2><p>Benutzer erben alle Rechte ihrer zugewiesenen Rolle.</p></div><button type="button" class="ghost role-close">×</button></div><div id="roleList" class="role-list"></div><form id="roleForm"><input type="hidden" name="id"><div class="form-grid"><label>Rollenname<input name="name" required maxlength="100"></label><label>Basistyp<select name="baseRole"><option value="VIEWER">Leser</option><option value="EDITOR">Sachbearbeiter</option><option value="ADMIN">Administrator</option></select></label></div><div id="permissionList" class="permission-grid"></div><div id="roleError" class="error"></div><div class="actions"><button type="button" id="newRole" class="secondary">Neue Rolle</button><button type="submit">Rolle speichern</button></div></form>';document.body.append(dialog);dialog.querySelector('.role-close').onclick=()=>dialog.close();button.onclick=async()=>{dialog.showModal();await loadRoles();resetRoleForm()};$('#newRole').onclick=resetRoleForm;$('#roleForm').onsubmit=saveRole;const originalUsers=$('#usersBtn').onclick;$('#usersBtn').onclick=async()=>{await loadRoles();originalUsers()};auditLabels.ROLE_CREATED='Rolle angelegt';auditLabels.ROLE_UPDATED='Rolle geändert';auditLabels.ROLE_DELETED='Rolle gelöscht';renderUsers=function(){$('#userList').innerHTML=users.map(u=>`<div class="user-row" data-id="${u.id}"><div><b>${esc(u.displayName)}</b><small>${esc(u.username)} · ${esc(u.roleName)}</small></div><span class="import-status ${u.active?'success':'rejected'}">${u.active?'Aktiv':'Gesperrt'}</span><button type="button" class="danger delete-user" data-id="${u.id}">Löschen</button></div>`).join('');document.querySelectorAll('.user-row').forEach(row=>row.onclick=e=>{if(e.target.classList.contains('delete-user'))return;const u=users.find(x=>x.id===row.dataset.id),f=$('#userForm');for(const key of ['id','username','displayName'])f.elements[key].value=u[key];f.elements.roleId.value=u.roleId;f.elements.active.checked=u.active;f.elements.password.value='';f.elements.password.required=false;$('#userError').textContent=''});document.querySelectorAll('.delete-user').forEach(remove=>remove.onclick=async()=>{const u=users.find(x=>x.id===remove.dataset.id);if(!confirm(`Benutzer ${u.username} wirklich löschen?`))return;try{await json(`/api/users/${u.id}`,{method:'DELETE'});await loadUsers()}catch(e){$('#userError').textContent=e.message}})};const oldReset=resetUserForm;resetUserForm=function(){oldReset();if(roles.length)form.elements.roleId.value=roles[0].id}}
async function loadRoles(){[roles,permissionCatalog]=await Promise.all([json('/api/roles'),json('/api/roles/permissions')]);const select=$('#userForm').elements.roleId;select.innerHTML=roles.map(role=>`<option value="${role.id}">${esc(role.name)}</option>`).join('');renderRoles()}
function renderRoles(){$('#roleList').innerHTML=roles.map(role=>`<div class="role-row" data-role-id="${role.id}"><div><b>${esc(role.name)}</b><small>${role.permissions.length} Rechte · ${role.systemRole?'Systemrolle':'Eigene Rolle'}</small></div>${role.systemRole?'':`<button type="button" class="danger" data-role-delete="${role.id}">Löschen</button>`}</div>`).join('');document.querySelectorAll('[data-role-id]').forEach(row=>row.onclick=event=>{if(event.target.dataset.roleDelete)return;const role=roles.find(value=>value.id===row.dataset.roleId),form=$('#roleForm');form.elements.id.value=role.id;form.elements.name.value=role.name;form.elements.baseRole.value=role.baseRole;permissionCatalog.forEach(permission=>form.elements[`permission_${permission.value}`].checked=role.permissions.includes(permission.value));$('#roleError').textContent=''});document.querySelectorAll('[data-role-delete]').forEach(button=>button.onclick=async event=>{event.stopPropagation();if(!confirm('Rolle wirklich löschen?'))return;try{await json(`/api/roles/${button.dataset.roleDelete}`,{method:'DELETE'});await loadRoles()}catch(e){$('#roleError').textContent=e.message}})}
function resetRoleForm(){const form=$('#roleForm');form.reset();form.elements.id.value='';$('#permissionList').innerHTML=permissionCatalog.map(permission=>`<label><input type="checkbox" name="permission_${permission.value}"> ${esc(permission.label)}</label>`).join('');$('#roleError').textContent=''}
async function saveRole(event){event.preventDefault();const form=event.target,id=form.elements.id.value,payload={name:form.elements.name.value,baseRole:form.elements.baseRole.value,permissions:permissionCatalog.filter(permission=>form.elements[`permission_${permission.value}`].checked).map(permission=>permission.value)};try{await json(id?`/api/roles/${id}`:'/api/roles',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadRoles();resetRoleForm()}catch(e){$('#roleError').textContent=e.message}}
const openEditWithTemplateCompany=openEdit;
openEdit=function(){
    const grid=$('#editForm .form-grid');
    if(!$('#templateCompanyInput'))grid.insertAdjacentHTML('beforeend','<label class="wide">Firma für Word-Dokumentvorlagen<input id="templateCompanyInput" name="templateCompany" maxlength="255" list="templateCompanyOptions" placeholder="Leer: automatisch nach Begünstigtem"><datalist id="templateCompanyOptions"></datalist><small>Firmenname aus der Vorlagenverwaltung auswählen. * verwendet die allgemeine Vorlage.</small></label>');
    if(!$('#lcCompanySelect'))grid.insertAdjacentHTML('beforeend','<label class="wide">Firma / Gesellschaft<select name="companyId" id="lcCompanySelect"><option value="">Standardfirma (bisherige Zuordnung)</option></select><small>Bestimmt Firmenstammdaten, Logo und Firmenvorlage. Die bisherige Vorlagenfirma wird nur ohne Gesellschaftszuordnung verwendet.</small></label>');
    openEditWithTemplateCompany();
    const selectedId=activeLc.companyId;
    $('#lcCompanySelect').innerHTML='<option value="">Standardfirma (bisherige Zuordnung)</option>'+(selectedId?'<option value="'+selectedId+'" selected>Firma #'+selectedId+'</option>':'');
    json('/api/companies/choices').then(choices=>{$('#lcCompanySelect').innerHTML='<option value="">Standardfirma (bisherige Zuordnung)</option>'+choices.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#lcCompanySelect').value=selectedId||''}).catch(()=>{});
    $('#templateCompanyInput').value=activeLc.templateCompany||'';
    json('/api/document-templates/companies').then(names=>{$('#templateCompanyOptions').innerHTML=names.map(name=>`<option value="${esc(name)}"></option>`).join('')}).catch(()=>{});
};
function refreshCompanyFilter(){
    let select=$('#lcCompanyFilter');
    if(!select){select=document.createElement('select');select.id='lcCompanyFilter';select.setAttribute('aria-label','LC-Akten nach Firma filtern');$('#lcSort').before(select);select.onchange=render;}
    const selected=select.value;
    select.innerHTML='<option value="">Alle Firmen</option><option value="unassigned">Ohne Firmenzuordnung</option>'+dossierCompanies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
    if([...select.options].some(o=>o.value===selected))select.value=selected;
}
const showWithCompanyLabel=show;
show=async function(id){await showWithCompanyLabel(id);if(activeLc?.id!==id)return;const heading=$('#detail .panelhead p');if(heading){const label=document.createElement('span');label.textContent=' · '+dossierCompanyName(activeLc);heading.append(label);}};
ensureTrainingUi();setupAppNavigation();setupWorkspacePresets();setupDocumentBatchUpload();ensureRoleUi();init().then(()=>examinationWorkspaceChannel?.postMessage({type:'WORKSPACE_READY',source:examinationWorkspaceTabId}));
function templateFormData(form){const body=new FormData(form);if(!body.get('companyId'))body.delete('companyId');return body;}
async function setupTemplateCompanies(){
    const form=$('#templateForm');
    if(!$('#downloadTemplateSample')){
        const block=document.createElement('div');block.className='template-help';
        block.innerHTML='<b>Mit einer Mustervorlage beginnen</b><p>Dokumenttyp unten auswählen, Muster herunterladen, in Word gestalten und als DOCX wieder hochladen. Platzhalter in doppelten geschweiften Klammern unverändert lassen.</p><a id="downloadTemplateSample" class="button-link">Word-Muster herunterladen</a>';
        form.before(block);
        const updateLink=()=>{$('#downloadTemplateSample').href='/api/document-templates/sample?type='+encodeURIComponent(form.elements.type.value);};
        form.elements.type.addEventListener('change',updateLink);
        form.addEventListener('reset',()=>setTimeout(updateLink,0));
        updateLink();
    }
    if(!form.elements.companyId)form.querySelector('.form-grid').insertAdjacentHTML('afterbegin','<label>Firma / Gesellschaft<select name="companyId"></select><small>Firmenvorlagen bleiben auch bei einer Umbenennung zugeordnet.</small></label>');
    const choices=await json('/api/companies/choices');
    form.elements.companyId.innerHTML='<option value="">Allgemeine oder bisherige Namensvorlage</option>'+choices.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
}

// Training completion is separate from importing business records.
const renderTrainingWithBusinessImport=renderTraining;
renderTraining=function(){
    renderTrainingWithBusinessImport();
    setupTrainingPreviewSizes();
    $('#trainingModeNotice')?.remove();
    $('#trainingStatus').insertAdjacentHTML('afterbegin','<div id="trainingModeNotice" class="template-help"><b>Trainingsmodus — Erkennung verbessern</b><p>„Nur Training abschließen“ speichert die geprüften Trainingsdaten, ohne eine LC-Akte anzulegen oder zu ändern. Die Qualitätsampel bewertet die Eignung für den Geschäftsimport, nicht den Trainingsabschluss.</p></div>');
    let finish=$('#finishTrainingOnly');
    if(!finish){finish=document.createElement('button');finish.id='finishTrainingOnly';finish.type='button';finish.textContent='Nur Training abschließen';$('#confirmTraining').before(finish);finish.onclick=finishTrainingOnly;}
    finish.classList.toggle('hidden',trainingItem.status==='CONFIRMED');
    $('#confirmTraining').classList.add('secondary');
    $('#confirmTraining').textContent='Training abschließen und Geschäftsdaten übernehmen';
    $('#confirmTraining').classList.toggle('hidden',trainingItem.status==='CONFIRMED'||trainingItem.preview.messageType==='MT760');
    $('#confirmTraining').onclick=()=>{if(confirm('Damit werden Geschäftsdaten übernommen: Ein LC wird angelegt/verknüpft oder ein Amendment importiert. Fortfahren?'))confirmTraining();};
};
async function finishTrainingOnly(){
    if(!trainingItem?.sessionId)return;
    const button=$('#finishTrainingOnly');button.disabled=true;
    clearTimeout(trainingSaveTimer);clearTimeout(trainingQualityTimer);
    try{
        await json(`/api/training/${trainingItem.sessionId}/finish`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(trainingDraftPayload())});
        trainingItem.status='CONFIRMED';
        await openTrainingSession(trainingItem.sessionId);
        $('#trainingError').textContent='';
        $('#trainingModeNotice').textContent='Training abgeschlossen. Es wurden keine Geschäftsdaten angelegt oder geändert. Export und Ansicht bleiben über die Trainingshistorie verfügbar.';
        await loadDashboardDrafts();
    }catch(error){$('#trainingError').textContent=error.message;}
    finally{button.disabled=false;}
}
const openTrainingSeparated=openTraining;
openTraining=function(){openTrainingSeparated();$('#finishTrainingOnly')?.classList.add('hidden');$('#confirmTraining').textContent='Geschäftsdaten übernehmen';};

function setupTrainingPreviewSizes(){
    document.querySelectorAll('.training-field').forEach(row=>{
        const text=row.querySelector('textarea').value;
        const expanded=text.length>400||text.split(/\r?\n/).length>6;
        const frame=row.querySelector('.snippet-frame');
        frame.id='trainingSnippet-'+row.dataset.index;
        frame.tabIndex=0;
        frame.setAttribute('role','region');
        frame.setAttribute('aria-label','PDF-Ausschnitt; lange Inhalte können gescrollt werden');
        const button=document.createElement('button');
        button.type='button';button.className='secondary preview-size-toggle';
        button.setAttribute('aria-controls',frame.id);
        const setExpanded=value=>{
            row.classList.toggle('preview-expanded',value);
            button.setAttribute('aria-expanded',String(value));
            button.textContent=value?'Kompakte Vorschau':'Große Vorschau';
        };
        button.onclick=()=>setExpanded(!row.classList.contains('preview-expanded'));
        row.querySelector('.pdf-context').append(button);
        setExpanded(expanded);
    });
}

function lcCockpitCards(lc,documents,review,tasks){
    return [
        ['Beteiligte',lc.beneficiary||'Nicht erfasst','Begünstigter · Antragsteller: '+(lc.applicant||'Nicht erfasst'),'admin'],
        ['Betrag',money(lc.amount,lc.currency),statusLabel(lc.status||'RECEIVED'),'admin'],
        ['Dokumentenakte',documents==null?'Nicht verfügbar':documents.length+' Dokumente','Dokumente und Anlagen öffnen','documents'],
        ['Automatische Vorprüfung',review==null?'Nicht verfügbar':review.discrepancies+' Abweichungen · '+review.warnings+' Hinweise','Fachliche Endprüfung bleibt erforderlich','checks'],
        ['Aufgaben',tasks==null?'Nicht verfügbar':tasks.filter(task=>!task.completed).length+' offen','Bearbeiter: '+(lc.assignedTo||'Nicht zugewiesen'),'tasks'],
        ['Fristen','Ablauf: '+fmtDate(lc.expiryDate),'Spätester Versand: '+fmtDate(lc.latestShipmentDate)+' · Wiedervorlage: '+fmtDate(lc.followUpDate),'history']
    ];
}
const showWithOperationalCockpit=show;
show=async function(id){
    synchronizeExaminationLc(id);
    await showWithOperationalCockpit(id);
    if(activeLc?.id!==id)return;
    if(!receivingSynchronizedLcSelection)examinationWorkspaceChannel?.postMessage({type:'LC_SELECTED',lcId:id,source:examinationWorkspaceTabId});
    const overview=$('#detail .dossier-section[data-section="overview"]');
    if(!overview)return;
    overview.querySelector('.lc-operational-cockpit')?.remove();
    const block=document.createElement('div');block.className='lc-operational-cockpit';
    block.setAttribute('aria-live','polite');block.textContent='Aktenüberblick wird geladen …';overview.prepend(block);
    const [documents,review,tasks,timeline]=await Promise.all([
        json(`/api/lcs/${id}/documents`).catch(()=>null),
        json(`/api/lcs/${id}/document-checks`).catch(()=>null),
        json(`/api/lcs/${id}/tasks`).catch(()=>null),
        json(`/api/lcs/${id}/timeline`).catch(()=>null)
    ]);
    if(activeLc?.id!==id||!block.isConnected)return;
    block.innerHTML='<h3>LC-Cockpit</h3><div class="grid">'+lcCockpitCards(activeLc,documents,review,tasks).map(([title,value,note,section])=>`<div class="card"><small>${esc(title)}</small><b>${esc(value)}</b><p>${esc(note)}</p><button type="button" class="secondary" data-cockpit-section="${section}">${esc(title)} öffnen</button></div>`).join('')+'</div>';
    block.querySelectorAll('[data-cockpit-section]').forEach(button=>button.onclick=()=>activateDossierSection(button.dataset.cockpitSection));
    const activity=document.createElement('section');
    activity.innerHTML='<div class="sectionhead"><h3>Letzte Aktivitäten</h3><button type="button" class="secondary">Gesamten Verlauf öffnen</button></div><div class="timeline-list">'+(timeline==null?'<p>Der Verlauf konnte nicht geladen werden. Bitte die Akte erneut öffnen.</p>':timelineHtml(timeline.slice(0,5)))+'</div>';
    activity.querySelector('button').onclick=()=>activateDossierSection('history');
    block.append(activity);
    if(examinationWorkspacePanel==='documents'||examinationWorkspacePanel==='checks')activateDossierSection(examinationWorkspacePanel);
};

function positionExaminationWorkspaceWindows(windows){
    if(typeof window.getScreenDetails!=='function')return;
    window.getScreenDetails().then(details=>{
        const screens=(details.screens||[]).filter(screen=>!screen.isPrimary);
        windows.forEach((handle,index)=>{const screen=screens[index];if(!screen||handle.closed)return;try{handle.moveTo(screen.availLeft??screen.left,screen.availTop??screen.top);handle.resizeTo(screen.availWidth??screen.width,screen.availHeight??screen.height)}catch(error){/* Browser or OS may disallow programmatic positioning. */}});
    }).catch(()=>{/* The standard draggable-window fallback remains available. */});
}
function setupWorkspacePresets(){
    const control=document.createElement('div');control.className='workspace-control';control.innerHTML='<small>ARBEITSPLATZ</small><select id="workspacePreset" aria-label="Arbeitsplatz auswählen"><option value="standard">Standard</option><option value="examination">LC-Prüfung</option><option value="professional">Drei Bildschirme</option></select><button type="button" id="applyWorkspacePreset">Arbeitsplatz öffnen</button><small id="workspacePresetHint" aria-live="polite"></small>';
    $('#appNav').insertBefore(control,$('.app-nav-footer'));
    const select=$('#workspacePreset'),hint=$('#workspacePresetHint'),lcButton=document.querySelector('[data-app-section="lcs"]'),cockpitButton=document.querySelector('[data-app-section="cockpit"]'),childWindow=examinationWorkspacePanel==='documents'||examinationWorkspacePanel==='checks';
    if(childWindow){control.classList.add('hidden');select.value='professional';lcButton.click();return;}
    let saved='standard';try{const candidate=localStorage.getItem(workspacePresetStorageKey);if(['standard','examination','professional'].includes(candidate))saved=candidate}catch(error){}
    select.value=saved;
    if(saved==='standard')cockpitButton.click();else lcButton.click();
    if(saved==='professional')hint.textContent='Gespeichert. Erneut öffnen, um Zusatzfenster zu starten.';
    $('#applyWorkspacePreset').onclick=()=>{
        const preset=select.value;try{localStorage.setItem(workspacePresetStorageKey,preset)}catch(error){}
        if(preset==='standard'){cockpitButton.click();hint.textContent='Standardansicht geöffnet.';return;}
        lcButton.click();
        if(preset==='examination'){hint.textContent='LC-Aktenansicht geöffnet. Dokumente lassen sich separat öffnen.';if(activeLc)show(activeLc.id);return;}
        const openWorkspace=(panel,name)=>{
            const existing=examinationWorkspaceWindows.find(item=>item.panel===panel&&!item.handle.closed);
            if(existing){existing.handle.focus();return existing.handle;}
            const url=new URL('/',location.href);url.searchParams.set('workspace',panel);
            const handle=window.open(url.toString(),name,'popup,width=1100,height=850,resizable=yes,scrollbars=yes');
            if(handle){try{handle.opener=null}catch(error){}examinationWorkspaceWindows.push({panel,handle});}
            return handle;
        };
        const documents=openWorkspace('documents','clm-examination-documents');
        const checks=openWorkspace('checks','clm-examination-checks');
        if(!documents||!checks){hint.textContent='Ein Zusatzfenster wurde blockiert. Bitte Pop-ups erlauben; geöffnete Fenster können Sie manuell auf weitere Bildschirme ziehen.';return;}
        hint.textContent='Prüfung, Dokumente und Befunde geöffnet. Fenster bei Bedarf auf die Bildschirme ziehen.';
        positionExaminationWorkspaceWindows([documents,checks]);
        if(activeLc)show(activeLc.id);
    };
}
